window.ScripturaLexicons.BDAG_PART_0018 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akoe-bdag\" data-source=\"BDAG\" data-search=\"ἀκοή akoe audição escuta ouvido notícia fama relato mensagem proclamação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκοή</td><td>Substantivo</td><td>audição; ouvido; notícia; mensagem</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akoimetos-bdag\" data-source=\"BDAG\" data-search=\"ἀκοίμητος akoimetos sem dormir sempre ativo inquieto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκοίμητος</td><td>Adjetivo</td><td>sem dormir; sempre ativo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akoloutheo-bdag\" data-source=\"BDAG\" data-search=\"ἀκολουθέω akoloutheo seguir acompanhar discípulo obedecer suceder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκολουθέω</td><td>Verbo</td><td>seguir; acompanhar; ser discípulo; obedecer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akolouthos-bdag\" data-source=\"BDAG\" data-search=\"ἀκόλουθος akolouthos seguinte subsequente apropriado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκόλουθος</td><td>Adjetivo</td><td>seguinte; subsequente; apropriado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akontizo-bdag\" data-source=\"BDAG\" data-search=\"ἀκοντίζω akontizo lançar arremessar lança granizo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκοντίζω</td><td>Verbo</td><td>lançar; arremessar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akorestos-bdag\" data-source=\"BDAG\" data-search=\"ἀκόρεστος akorestos insaciável desejo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκόρεστος</td><td>Adjetivo</td><td>insaciável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akoustos-bdag\" data-source=\"BDAG\" data-search=\"ἀκουστός akoustos audível chegar ouvidos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκουστός</td><td>Adjetivo</td><td>audível</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akoutizo-bdag\" data-source=\"BDAG\" data-search=\"ἀκουτίζω akoutizo fazer ouvir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκουτίζω</td><td>Verbo</td><td>fazer ouvir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akouo-bdag\" data-source=\"BDAG\" data-search=\"ἀκούω akouo ouvir escutar tomar conhecimento atender obedecer ser chamado compreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκούω</td><td>Verbo</td><td>ouvir; escutar; tomar conhecimento; compreender</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akrasia-bdag\" data-source=\"BDAG\" data-search=\"ἀκρασία akrasia falta autocontrole intemperança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκρασία</td><td>Substantivo</td><td>falta de autocontrole; intemperança</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akrates-bdag\" data-source=\"BDAG\" data-search=\"ἀκρατής akrates sem autocontrole dissoluto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκρατής</td><td>Adjetivo</td><td>sem autocontrole; dissoluto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akratos-bdag\" data-source=\"BDAG\" data-search=\"ἄκρατος akratos não misturado puro força total vinho ira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄκρατος</td><td>Adjetivo</td><td>não misturado; em plena força</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akribeia-bdag\" data-source=\"BDAG\" data-search=\"ἀκρίβεια akribeia exatidão precisão rigor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκρίβεια</td><td>Substantivo</td><td>exatidão; precisão; rigor</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akribeuomai-bdag\" data-source=\"BDAG\" data-search=\"ἀκριβεύομαι akribeuomai prestar atenção rigorosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκριβεύομαι</td><td>Verbo</td><td>prestar rigorosa atenção</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akribes-bdag\" data-source=\"BDAG\" data-search=\"ἀκριβής akribes exato rigoroso estrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκριβής</td><td>Adjetivo</td><td>exato; rigoroso; estrito</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akriboo-bdag\" data-source=\"BDAG\" data-search=\"ἀκριβόω akriboo averiguar precisamente exatamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκριβόω</td><td>Verbo</td><td>averiguar precisamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-akribos-bdag\" data-source=\"BDAG\" data-search=\"ἀκριβῶς akribos exatamente cuidadosamente precisamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀκριβῶς</td><td>Advérbio</td><td>exatamente; cuidadosamente; precisamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-akoe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akoḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Forma <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκουή\" data-meanings=\"audição; forma antiga\">ἀκουή</span> já em Homero; frequente em inscrições, papiros e LXX; PsSol 8:5; ApcSed; ApcMos 8; EpArist; Test12Patr; Fílon; Josefo; Just.; Ath.)\n<span class=\"sense-number\">1.</span> <strong>A faculdade de ouvir, audição</strong> (Fílon, <em>Rer. Div. Her.</em> 12; Did., <em>Gen.</em> 162, 21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 12.17</a>; o sentido 3 também é provável.\n<span class=\"sense-number\">2.</span> <strong>O ato de ouvir, escuta</strong>: com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βλέμμα\" data-meanings=\"olhar\">βλέμμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκοῇ ἀκούειν\" data-meanings=\"ouvir com a audição\">ἀκοῇ ἀκούειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.26</a> (ambos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Is 6.9</a>); B 9:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἀ. ὠτίου ὑπακούειν\" data-meanings=\"obedecer ao ouvir com o ouvido\">εἰς ἀ. ὠτίου ὑπακούειν</span>, isto é, assim que se ouve, B 9:1 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.17.45\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 17.45</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.22.45\" target=\"_blank\" rel=\"noopener noreferrer\">2 Sm 22.45</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. πίστεως\" data-meanings=\"audição da fé\">ἀ. πίστεως</span> = “a audição que os cristãos chamam fé”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a> (S. Williams, NTS 35, 1989, 82–93), mas a maioria prefere 4b.\n<span class=\"sense-number\">3.</span> <strong>O órgão com que se ouve, ouvido</strong>, especialmente plural: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ ἀκοαί\" data-meanings=\"os ouvidos\">αἱ ἀκοαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.35</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰσφέρειν εἰς τὰς ἀ.\" data-meanings=\"trazer aos ouvidos\">εἰσφέρειν εἰς τὰς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.20</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς τὰς ἀ. τινος\" data-meanings=\"aos ouvidos de alguém\">εἰς τὰς ἀ. τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.1</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"νωθρὸς ταῖς ἀ.\" data-meanings=\"lento nos ouvidos\">νωθρὸς ταῖς ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.11</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κνήθεσθαι τὴν ἀ.\" data-meanings=\"ter coceira no ouvido\">κνήθεσθαι τὴν ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4.3</a>; figuradamente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περιτέμνειν τὰς ἀ.\" data-meanings=\"circuncidar os ouvidos\">περιτέμνειν τὰς ἀ.</span> = tornar atento, B 9:4; 10:12.\n<span class=\"sense-number\">4.</span> <strong>Aquilo que é ouvido.</strong> <strong>a.</strong> <strong>Fama, notícia, rumor</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">14.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">24.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">13.7</a>; 1 Cl 47:7. <strong>b.</strong> <strong>Relato, mensagem</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστεύειν τῇ ἀ.\" data-meanings=\"crer na mensagem\">πιστεύειν τῇ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.16 s.</a>; 1 Cl 16:3 (todos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.53.1\" target=\"_blank\" rel=\"noopener noreferrer\">Is 53.1</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξ ἀ. πίστεως\" data-meanings=\"como resultado de mensagem/proclamação que suscitou fé\">ἐξ ἀ. πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγος τῆς ἀκοῆς\" data-meanings=\"palavra da proclamação\">λόγος τῆς ἀκοῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγος ἀκοῆς παρ’ ἡμῶν τοῦ θεοῦ\" data-meanings=\"palavra da proclamação divina que sai de nós\">λόγος ἀκοῆς παρ’ ἡμῶν τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 2.13</a>. — A. Oepke, <em>Die Missionspredigt d. Ap. Pls.</em>, 1920, 40 ss. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούω\" data-meanings=\"ouvir\">ἀκούω</span>. M-M. TW. Sv.</p></section></article><article id=\"entry-akoimetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοίμητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akoímētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κοιμάω\" data-meanings=\"fazer dormir\">κοιμάω</span>; desde Aeschyl., <em>Pr.</em> 139; Aelian, <em>NA</em> 11, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πῦρ ἄσβεστον καὶ ἀ.\" data-meanings=\"fogo inextinguível e sempre ativo\">πῦρ ἄσβεστον καὶ ἀ.</span>; POxy 1468, 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 7.10</a>; ApcEsdr 4:20; Fílon; SibOr 2, 181; Mel., Fgm. 8b 31.) <strong>Que não pode ser posto a dormir, sempre ativo</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σκώληκες ἀ.\" data-meanings=\"vermes inquietos\">σκώληκες ἀ.</span> ApcPt 12:27; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. πνεῦμα\" data-meanings=\"espírito sempre ativo\">ἀ. πνεῦμα</span> IPol 1:3. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κεῖμαι\" data-meanings=\"jazer\">κεῖμαι</span>. </p></section></article><article id=\"entry-akoloutheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκολουθέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akolouthéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">impv. ἀκολούθει; impf. ἠκολούθουν; fut. ἀκολουθήσω; 1 aor. ἠκολούθησα; pf. ἠκολούθηκα</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Denominativo de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκόλουθος\" data-meanings=\"seguinte\">ἀκόλουθος</span>; Tucídides, Aristófanes+; Did., <em>Gen.</em> 49, 17 restaurado.) Primariamente “seguir”.\n<span class=\"sense-number\">1.</span> Literalmente, <strong>mover-se atrás de alguém na mesma direção, vir depois, seguir</strong>. Absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ προάγοντες κ. οἱ ἀκολουθοῦντες\" data-meanings=\"os que iam adiante e os que seguiam\">οἱ προάγοντες κ. οἱ ἀκολουθοῦντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11.9</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 10.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.8</a>. Com dativo de pessoa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.58\" target=\"_blank\" rel=\"noopener noreferrer\">26.58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.4 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">11.31</a>; IPhld 11:1; Hv 3, 8, 4; 7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠκολούθει τῷ Ἰησοῦ Σίμων Πέτρος κ. ἄλλος μαθητής\" data-meanings=\"Simão Pedro e outro discípulo seguiam Jesus\">ἠκολούθει τῷ Ἰησοῦ Σίμων Πέτρος κ. ἄλλος μαθητής</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.15</a>.\n<span class=\"sense-number\">2.</span> <strong>Seguir ou acompanhar alguém que vai à frente, acompanhar, ir junto.</strong> Frequentemente da multidão que segue Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">8.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">12.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">14.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">9.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.2</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετά\" data-meanings=\"com\">μετά</span> + genitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.49</a> é diferente: “não segue [a ti] conosco”. Hebraisticamente com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὀπίσω τινός\" data-meanings=\"atrás de alguém\">ὀπίσω τινός</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.34</a>. Das obras que acompanham alguém ao mundo vindouro: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἔργα αὐτῶν ἀκολουθεῖ μετ’ αὐτῶν\" data-meanings=\"suas obras os acompanham\">τὰ ἔργα αὐτῶν ἀκολουθεῖ μετ’ αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.13</a>.\n<span class=\"sense-number\">3.</span> Com transição para o figurado, <strong>seguir alguém como discípulo, ser discípulo, seguir</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκολούθει μοι\" data-meanings=\"segue-me\">ἀκολούθει μοι</span> = “sê meu discípulo”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.9</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">8.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">19.21</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">27 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">8.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">27 s.</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.37 s.</a> o verbo tem o sentido 2, mas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">40</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">43</a> o sentido 3. — T. Arvedson, SvTK 7, 1931, 134–161; E. Schweizer, <em>Lordship and Discipleship</em>, 1960; A. Schulz, <em>Nachfolgen u. Nachahmen</em>, 1962; G. Kilpatrick, BT 7, 1956, 5 s.; R. Thysman, ETL 42, 1966, 138–175; T. Aerts, ibid., 475–512.\n<span class=\"sense-number\">4.</span> Em geral, <strong>conformar-se a, seguir, obedecer</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῖς ἔθεσιν\" data-meanings=\"aos costumes\">τοῖς ἔθεσιν</span> Dg 5:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῖς νομίμοις τ. δεσπότου\" data-meanings=\"aos estatutos do Senhor\">τοῖς νομίμοις τ. δεσπότου</span> 1 Cl 40:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῇ ὁδῷ τῆς ἀληθείας\" data-meanings=\"ao caminho da verdade\">τῇ ὁδῷ τῆς ἀληθείας</span> 1 Cl 35:5; ao bispo, ISm 8:1; a um cismático, IPhld 3:3; Hm 6, 2, 9.\n<span class=\"sense-number\">5.</span> <strong>Vir depois de algo em sequência, seguir</strong>, de coisas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν λοιπῶν τῶν ἀκολουθούντων πάντων\" data-meanings=\"de todas as demais coisas que seguem\">τῶν λοιπῶν τῶν ἀκολουθούντων πάντων</span> Hs 5, 5, 1; com dativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.17</a> v.l. — B. 699. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκόλουθος\" data-meanings=\"seguinte\">ἀκόλουθος</span>. EDNT. M-M. TW. Sv.</p></section></article><article id=\"entry-akolouthos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόλουθος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akólouthos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Bacchylides, Sófocles+.) <strong>Relativo ao que vem depois de outra coisa em sequência, seguinte</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καὶ τῶν λοιπῶν τῶν ἀκολούθων πάντων\" data-meanings=\"e de todas as demais coisas que se seguiram\">καὶ τῶν λοιπῶν τῶν ἀκολούθων πάντων</span> Hs 5, 5, 1 (cód. A). Com genitivo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἀ. τούτων\" data-meanings=\"as coisas que seguem estas\">τὰ ἀ. τούτων</span> Hm 8:4, 10; compare Hs 9, 15, 3. Com dativo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ τούτοις ἀ.\" data-meanings=\"as coisas que seguem estas\">τὰ τούτοις ἀ.</span> = “e assim por diante”, MPol 8:2; 9:2. Absoluto, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἐστιν\" data-meanings=\"seguem-se\">ἀ. ἐστιν</span> IEph 14:1; também <strong>apropriado, conveniente</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅπου καὶ ἀ. ἦν\" data-meanings=\"onde também era apropriado\">ὅπου καὶ ἀ. ἦν</span> = “em lugar apropriado”, MPol 18:1. — DELG.</p></section></article><article id=\"entry-akontizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκοντίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akontízō⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. pass. ἠκοντίσθην</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄκων\" data-meanings=\"dardo; lança\">ἄκων</span>; Homero, Heródoto e outros; LXX; TestSol 7:8; Test12Patr; JosAs; GrBar 5:3; Josefo.) Literalmente, “<strong>lançar uma lança</strong>”, depois em geral <strong>lançar, arremessar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χάλαζα … ἠκοντίσθη ἀπ’ οὐρανοῦ\" data-meanings=\"granizo foi arremessado do céu\">χάλαζα … ἠκοντίσθη ἀπ’ οὐρανοῦ</span> AcPl Ha 5, 7.</p></section></article><article id=\"entry-akorestos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκόρεστος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akórestos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κόρος\" data-meanings=\"saciedade\">κόρος</span>; Ésquilo e outros; em Homero <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκόρητος\" data-meanings=\"insaciável\">ἀκόρητος</span>; PCairMasp 89 III, 6; Mel.) Figuradamente, <strong>insaciável</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πόθος\" data-meanings=\"desejo\">πόθος</span> — desejo de fazer o bem —, 1 Cl 2:2 (compare X., <em>Symp.</em> 8, 15, de amizade; Fílon, <em>Somn.</em> 1, 50; <em>Ebr.</em> 4; Mel., <em>P.</em> 20, 143; 50, 361).</p></section></article><article id=\"entry-akoustos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουστός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akoustós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Audível</strong> (Hinos Homéricos e outros; LXX; TestSol 22:1 B <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκουστὸν γέγονεν\" data-meanings=\"tornou-se audível\">ἀκουστὸν γέγονεν</span>; Fílon): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκουεστὸν ἐγένετο τοῖς ἀποστόλοις ὅτι\" data-meanings=\"chegou aos ouvidos dos apóstolos que\">ἀκουεστὸν ἐγένετο τοῖς ἀποστόλοις ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.1</a> D. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούω\" data-meanings=\"ouvir\">ἀκούω</span>.</p></section></article><article id=\"entry-akoutizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκουτίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akoutízō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἀκουτιῶ; 1 aor. ἠκούτισα</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(LXX; Syntipas p. 73, 1; manuscritos de Esopo [Ursing 78 s.]; Suda s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δογματίζω\" data-meanings=\"decretar; instruir\">δογματίζω</span>; Etym. Mag. p. 51, 32; Etym. Gud. 71, 5; Anecd. Gr. p. 366, 3.) <strong>Fazer ouvir</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. με ἀγαλλίασιν\" data-meanings=\"faz-me ouvir júbilo\">ἀ. με ἀγαλλίασιν</span> 1 Cl 18:8 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.10</a>). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούω\" data-meanings=\"ouvir\">ἀκούω</span>.</p></section></article><article id=\"entry-akouo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκούω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akoúō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἀκούσω / ἀκούσομαι; 1 aor. ἤκουσα; pf. ἀκήκοα; pass. fut. ἀκουσθήσομαι; 1 aor. ἠκούσθην; pf. ἤκουσται</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero+.) “<strong>Ouvir</strong>”, como resposta passiva a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λέγω\" data-meanings=\"dizer\">λέγω</span>.\n<span class=\"sense-number\">1.</span> Literalmente, <strong>ter ou exercer a faculdade da audição, ouvir.</strong> <strong>a.</strong> Absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ὦτα ἀκούουσιν\" data-meanings=\"os ouvidos ouvem\">τὰ ὦτα ἀκούουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κωφοὶ ἀ.\" data-meanings=\"surdos ouvem\">κωφοὶ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.5</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῖς ὠσὶν βαρέως ἀ.\" data-meanings=\"ser pesado de ouvido\">τοῖς ὠσὶν βαρέως ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.15</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Is 6.10</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκοῇ ἀ.\" data-meanings=\"ouvir com a audição\">ἀκοῇ ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.26</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Is 6.9</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούοντες οὐκ ἀκούουσιν\" data-meanings=\"ouvindo, não ouvem\">ἀκούοντες οὐκ ἀκούουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.13</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.18</a>. Nas fórmulas de desafio à audiência: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἔχων ὦτα ἀκούειν ἀκουέτω\" data-meanings=\"quem tem ouvidos para ouvir, ouça\">ὁ ἔχων ὦτα ἀκούειν ἀκουέτω</span>, com variações, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.15</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">13.9</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">43</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.9</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">14.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">3.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">13.9</a>.\n<strong>b.</strong> Com objeto. <strong>α.</strong> Coisa no acusativo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">13.17 ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 1.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν φωνήν\" data-meanings=\"a voz\">τὴν φωνήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν λόγον\" data-meanings=\"a palavra\">τὸν λόγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.20 ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.24</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πολέμους καὶ ἀκοὰς πολέμων\" data-meanings=\"guerras e rumores de guerras\">πολέμους καὶ ἀκοὰς πολέμων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν βλασφημίαν\" data-meanings=\"a blasfêmia\">τὴν βλασφημίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.65\" target=\"_blank\" rel=\"noopener noreferrer\">26.65</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄρρητα ῥήματα\" data-meanings=\"palavras inexprimíveis\">ἄρρητα ῥήματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12.4</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἀκουσθέντα\" data-meanings=\"o que foi ouvido\">τὰ ἀκουσθέντα</span> = a mensagem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.1</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠκούσθη ὁ λόγος εἰς τὰ ὦτα τῆς ἐκκλησίας\" data-meanings=\"a notícia chegou aos ouvidos da igreja\">ἠκούσθη ὁ λόγος εἰς τὰ ὦτα τῆς ἐκκλησίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.22</a>. <strong>β.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί τινος\" data-meanings=\"algo de alguém\">τί τινος</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἐπαγγελίαν, ἣν ἠκούσατέ μου\" data-meanings=\"a promessa que ouvistes de mim\">τὴν ἐπαγγελίαν, ἣν ἠκούσατέ μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.4</a>; também com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ\" data-meanings=\"de\">ἐκ</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρά\" data-meanings=\"da parte de\">παρά</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπό\" data-meanings=\"de\">ἀπό</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.26</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">15.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.22\" target=\"_blank\" rel=\"noopener noreferrer\">28.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 1.5</a>. <strong>γ.</strong> Coisa no genitivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῆς βλασφημίας\" data-meanings=\"da blasfêmia\">τῆς βλασφημίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.64</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συμφωνίας καὶ χορῶν\" data-meanings=\"música e danças\">συμφωνίας καὶ χορῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.25</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῆς φωνῆς\" data-meanings=\"da voz\">τῆς φωνῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.25</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">11.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">22.7</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν λόγων\" data-meanings=\"das palavras\">τῶν λόγων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.47</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ῥημάτων\" data-meanings=\"das declarações\">τῶν ῥημάτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.47</a>. Com genitivo de pessoa e particípio: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠκούσαμεν αὐτοῦ λέγοντος\" data-meanings=\"ouvimo-lo dizer\">ἠκούσαμεν αὐτοῦ λέγοντος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16.5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περί\" data-meanings=\"acerca de\">περί</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">24.24</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.2</a>. Imperativos: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄκουε\" data-meanings=\"ouve!\">ἄκουε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.29</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 6.4</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούσατε\" data-meanings=\"ouvi!\">ἀκούσατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">13.16</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συνίετε\" data-meanings=\"compreendei\">συνίετε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.10</a>.\n<span class=\"sense-number\">2.</span> Termo jurídico: <strong>ouvir um caso, conceder audiência a alguém</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐὰν μὴ ἀκούσῃ πρῶτον παρ’ αὐτοῦ\" data-meanings=\"se não o ouvir primeiro\">ἐὰν μὴ ἀκούσῃ πρῶτον παρ’ αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.22</a>.\n<span class=\"sense-number\">3.</span> <strong>Receber notícia ou informação sobre algo, tomar conhecimento.</strong> <strong>a.</strong> Absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">6.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.18</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναγγέλλειν\" data-meanings=\"anunciar\">ἀναγγέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">15.21</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.52.15\" target=\"_blank\" rel=\"noopener noreferrer\">Is 52.15</a>). <strong>b.</strong> De pessoa ou coisa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὗ οὐκ ἤκουσαν\" data-meanings=\"de quem não ouviram\">οὗ οὐκ ἤκουσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.14</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἀγάπην\" data-meanings=\"o amor\">τὴν ἀγάπην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 5</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἀναστροφήν\" data-meanings=\"a conduta\">τὴν ἀναστροφήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἔργα τοῦ Χριστοῦ\" data-meanings=\"as obras do Cristo\">τὰ ἔργα τοῦ Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἐνέδραν\" data-meanings=\"a emboscada\">τὴν ἐνέδραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.16</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν πίστιν\" data-meanings=\"a fé\">τὴν πίστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.4</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ὑπομονήν\" data-meanings=\"a perseverança\">τὴν ὑπομονήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.11</a>; passivo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούεται ἐν ὑμῖν πορνεία\" data-meanings=\"ouve-se que há imoralidade entre vós\">ἀκούεται ἐν ὑμῖν πορνεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.14</a>. <strong>c–f.</strong> Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περί\" data-meanings=\"acerca de\">περί</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">16.2</a>; com preposições indicando fonte: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">6.45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">12.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.13</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">4.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἠκούσθη ὅτι\" data-meanings=\"nunca se ouviu que\">οὐκ ἠκούσθη ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.32</a>; com acusativo e infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.18</a>; com acusativo e particípio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">3 Jo 4</a>.\n<span class=\"sense-number\">4.</span> <strong>Dar cuidadosa atenção a, escutar, atender.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούετε αὐτοῦ\" data-meanings=\"ouvi-o\">ἀκούετε αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.22</a> (os três com <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 18.15</a>); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.29</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.31\" target=\"_blank\" rel=\"noopener noreferrer\">31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.19</a>; com acusativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.47</a>. Absoluto, <strong>obedecer, escutar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.28</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.25</a>; “concordar”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">9.27</a>.\n<span class=\"sense-number\">5.</span> <strong>Prestar atenção ouvindo, escutar.</strong> Com genitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.60\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.60</a>. De Deus que ouve, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.34</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 3.7</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">11.41 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.14 s.</a>; AcPt Ox 849, 27. Absoluto, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθὼς ἠδύναντο ἀ.\" data-meanings=\"conforme eram capazes de ouvir\">καθὼς ἠδύναντο ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.33</a>.\n<span class=\"sense-number\">6.</span> <strong>Receber apelido ou outro rótulo identificador, ser chamado</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤκουσαν προδόται γονέων\" data-meanings=\"foram chamados traidores dos pais\">ἤκουσαν προδόται γονέων</span> Hv 2, 2, 2.\n<span class=\"sense-number\">7.</span> <strong>Ouvir e compreender uma mensagem, compreender.</strong> Absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 14.2</a>; talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.33</a>. Com acusativo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν νόμον\" data-meanings=\"a lei\">τὸν νόμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.21</a>; talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.14\" target=\"_blank\" rel=\"noopener noreferrer\">26.14</a>. Compare o jogo de palavras <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούοντες οὐκ ἀκούουσιν\" data-meanings=\"ouvindo, não compreendem\">ἀκούοντες οὐκ ἀκούουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.18</a>. Incluem-se aqui os imperativos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">13.9</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.9</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">14.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">3.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">13.9</a>. O verbo ocasionalmente funciona como presente perfectivo, “ouço” = “ouvi”, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 3.11</a>. — B-D-F §322. — B. 1037; 1339. DELG. M-M. TW. Sv.</p></section></article><article id=\"entry-akrasia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρασία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akrasía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Veja DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κεράννυμι\" data-meanings=\"misturar\">κεράννυμι</span>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κράτος\" data-meanings=\"força; domínio\">κράτος</span>; pré-socráticos e outros; = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκράτεια\" data-meanings=\"falta de domínio\">ἀκράτεια</span> Phryn. 524 s. Lob.) <strong>Falta de autocontrole, intemperança</strong> (Xenofonte e outros; Fílon; Jos., <em>Bell.</em> 1, 34; SibOr 1, 35; Tat. 2:1), especialmente com referência à atividade sexual: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα μὴ πειράζῃ ὑμᾶς ὁ σατανᾶς διὰ τὴν ἀ. ὑμῶν\" data-meanings=\"para que Satanás não vos tente por causa da vossa falta de autocontrole\">ἵνα μὴ πειράζῃ ὑμᾶς ὁ σατανᾶς διὰ τὴν ἀ. ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.25</a> — as variantes <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκαθαρσίας\" data-meanings=\"impureza\">ἀκαθαρσίας</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδικίας\" data-meanings=\"injustiça\">ἀδικίας</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλεονεξίας\" data-meanings=\"ganância\">πλεονεξίας</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πονηρίας\" data-meanings=\"maldade\">πονηρίας</span> não se harmonizam bem com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁρπαγῆς\" data-meanings=\"rapina\">ἁρπαγῆς</span>, ao passo que “intemperança” corresponde ao “copo”. Personificada como vício, Hs 9, 15, 3. — TW. Spicq. Sv.</p></section></article><article id=\"entry-akrates-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρατής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akratḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ésquilo, Tucídides e outros; Vett. Val. 39, 33; inscrições; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 27.20a</a>; EpArist 277; Fílon; Jos., <em>Ant.</em> 16, 399; Just.; Tat. 9, 1.) <strong>Sem autocontrole, dissoluto</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐγκρατής\" data-meanings=\"autocontrolado\">ἐγκρατής</span> Aristot., <em>EN</em> 7, 4, 1146b, 9 s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 3.3</a>, em lista de vícios. — M-M. TW.</p></section></article><article id=\"entry-akratos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄκρατος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ákratos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κεράννυμι\" data-meanings=\"misturar\">κεράννυμι</span>; desde Homero, que tem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄκρητος\" data-meanings=\"não misturado\">ἄκρητος</span>; LXX; PsSol 8:14; TestSol 18:31; Fílon; Jos., <em>Ant.</em> 17, 103.) <strong>Não misturado, puro.</strong> De <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἶνος\" data-meanings=\"vinho\">οἶνος</span> (Od. 24, 73; Hdt. 1, 207; Posidonius: 87 Fgm. 15, 4 Jac. 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 5.2</a>). Figuradamente (compare POxy 237 VII, 40 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄκρατος τῶν νόμων ἀποτομία\" data-meanings=\"o rigor não mitigado das leis\">ἄκρατος τῶν νόμων ἀποτομία</span>), da ira de Deus <strong>em plena força</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.10</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.32.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 32.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.74.9\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 74.9</a>; PsSol 8:14). Sobre vinho “misturado/não misturado”, veja B. Bandstra, “Wine”, ISBE IV 1070 e 1072; também R. Charles, ICC, Apocalipse ad loc. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄκρατος\" data-meanings=\"não misturado\">ἄκρατος</span> ocorre com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὀργή\" data-meanings=\"ira\">ὀργή</span> em Aeschyl., <em>Prom.</em> 678; Alcidamas em Aristot., <em>Rhet.</em> 1406a, 10; Jos., <em>Ant.</em> 5, 150; 17, 148. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κεράννυμι\" data-meanings=\"misturar\">κεράννυμι</span>. M-M.\n</p></section></article><article id=\"entry-akribeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκρίβεια</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akríbeia⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Conformidade estrita com uma norma ou padrão, exatidão, precisão</strong> (Tucídides e outros [veja Renehan 1975, 19]; papiros desde o séc. III a.C., por exemplo UPZ 110, 46 [164 a.C.]; POxy 471, 11 ss. [séc. I d.C.]; 237 VIII, 39 [séc. II d.C.]; veja também Preis.; LXX; En 106:12; EpArist 103; Fílon; Jos., <em>Ant.</em> 4, 309; 9, 208 e outros; Tat.; Mel., <em>HE</em> 4, 26, 13): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πεπαιδευμένος κατὰ ἀ. τοῦ πατρῴου νόμου\" data-meanings=\"instruído rigorosamente segundo a lei ancestral\">πεπαιδευμένος κατὰ ἀ. τοῦ πατρῴου νόμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.3</a> (Isocr. 7, 40 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. νόμων\" data-meanings=\"rigor das leis\">ἀ. νόμων</span>; Jos., <em>Vi.</em> 191). A. Baumgarten, “The Name of the Pharisees”, JBL 102, 1983, 411–428. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκριβής\" data-meanings=\"exato; rigoroso\">ἀκριβής</span>. M-M. Sv.\n</p></section></article><article id=\"entry-akribeuomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβεύομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akribeúomai⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περί τινος\" data-meanings=\"acerca de algo\">περί τινος</span> Sext. Emp., <em>Math.</em> 1, 71; passivo PAmh 154, 7 [séc. VI d.C.].) Em sentido ativo, <strong>prestar rigorosa atenção</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περὶ τῆς σωτηρίας\" data-meanings=\"acerca da salvação\">περὶ τῆς σωτηρίας</span> B 2:10. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκριβής\" data-meanings=\"exato; rigoroso\">ἀκριβής</span>.\n</p></section></article><article id=\"entry-akribes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦akribḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Heráclito+; inscrições, papiros, LXX; TestSol 4:1 D; Fílon; Jos., <em>Ant.</em> 2, 60; Just., Tat., Ath.; Iren. 5, 2, 3 [Harv. II 324, 3].) <strong>Exato, estrito, rigoroso.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατὰ τὴν ἀκριβεστάτην αἵρεσιν\" data-meanings=\"segundo a seita mais rigorosa\">κατὰ τὴν ἀκριβεστάτην αἵρεσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.5</a>. — DELG. M-M.\n</p></section></article><article id=\"entry-akriboo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akribóō⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. ἠκρίβωσα</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Eurípides, Xenofonte, Platão; Aristot., <em>Gen. Anim.</em> 5, 1, 780b, da incapacidade de distinguir cores; Aq. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.30.8\" target=\"_blank\" rel=\"noopener noreferrer\">Is 30.8</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.49.16\" target=\"_blank\" rel=\"noopener noreferrer\">49.16</a>; Fílon; Mel. [?], Fgm. 12, 4; Ath.) <strong>Fazer investigação detalhada sobre algo, averiguar precisamente/exatamente</strong> (Vett. Val. 265, 3; Fílon, <em>Op. M.</em> 77; Jos., <em>Bell.</em> 1, 648, de estudo cuidadoso; <em>Vi.</em> 365, de cuidado na escrita): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί παρά τινος\" data-meanings=\"algo da parte de alguém\">τί παρά τινος</span>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρ’ αὐτῶν τὸν χρόνον\" data-meanings=\"deles, o tempo\">παρ’ αὐτῶν τὸν χρόνον</span> — Herodes pressionou os magos para saber o tempo exato —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.7</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">16</a>. — Frisk s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκριβής\" data-meanings=\"exato\">ἀκριβής</span>. M-M.\n</p></section></article><article id=\"entry-akribos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀκριβῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦akribō̂s⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ésquilo, Heródoto+; inscrições, papiros, LXX; TestSol 10:6; 24:2; TestJob 31:1; EpArist; Fílon; Josefo; Just.; Ath. 11:1, <em>R.</em> 454, 4; Mel., <em>HE</em> 4, 26, 14; frequente em historiadores e também em autores médicos.) <strong>Relativo à conformidade estrita com uma norma ou padrão, com foco em atenção cuidadosa: exatamente, cuidadosamente, bem.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βλέπειν\" data-meanings=\"observar\">βλέπειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκούειν\" data-meanings=\"ouvir\">ἀκούειν</span> Hm 3:4; 4, 3, 7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσέχειν\" data-meanings=\"prestar atenção\">προσέχειν</span> B 7:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γινώσκειν\" data-meanings=\"conhecer\">γινώσκειν</span> Hs 9, 5, 5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατανοεῖν\" data-meanings=\"examinar; compreender\">κατανοεῖν</span> Hs 9, 6, 3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰδέναι\" data-meanings=\"saber\">εἰδέναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διδάσκειν\" data-meanings=\"ensinar\">διδάσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 18.25</a>; Pol 3:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γράφειν\" data-meanings=\"escrever\">γράφειν</span> Papias 2:15; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξετάζειν\" data-meanings=\"examinar\">ἐξετάζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.8</a>; Hs 9, 13, 6; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρακολουθεῖν\" data-meanings=\"acompanhar/investigar de perto\">παρακολουθεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.3</a>. Comparativo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκριβέστερον\" data-meanings=\"mais exatamente\">ἀκριβέστερον</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκτίθεσθαι\" data-meanings=\"explicar\">ἐκτίθεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 18.26</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">23.15</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">20</a>; “mais acuradamente”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">24.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. αὐτὰ γνωσόμεθα\" data-meanings=\"conheceremos estas coisas mais exatamente\">ἀ. αὐτὰ γνωσόμεθα</span> Hv 3, 10, 10; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἰδεῖν\" data-meanings=\"ver\">ἰδεῖν</span> Hs 9, 1, 3 (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μανθάνειν\" data-meanings=\"aprender\">μανθάνειν</span>). — L. Alexander, <em>The Preface to Luke’s Gospel</em>, 1993. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀκριβής\" data-meanings=\"exato\">ἀκριβής</span>. M-M.\n</p></section></article>"};
